182	    ev = await neatlogs.evidence({ sessionId }).catch((e) => ({ matched: false, error: e.message }));
183	    if ((ev.matched && ev.traces[0].summary.finalized) || now() >= until || active?.stopped) break;
184	    await new Promise((r) => setTimeout(r, 8000));
