186	  if (!ev.matched) return { state: ev.error ? 'error' : 'notfound', error: ev.error };
187	  const t = ev.traces[0];
188	  const s = t.summary;
189	  const text = [
190	    `trace ${s.traceId} · ${s.status} · ${s.spans} spans · ${s.toolCalls} tool calls · ${s.errors.length} failed`,
191	    ...s.sequence.map((x) => `  - ${x.name}${x.n > 1 ? ` x${x.n}` : ''}${x.error ? ' (error)' : ''}`),
192	  ].join('\n').slice(0, 4000);
193	  return { state: 'read', sessionId, summary: s, text };
