255	// One in-game test session against a plan: the pipeline's playtester, or the benchmark grader with the hidden plan.
256	async function playtestRun(mod, attempt, { plan, role, cwd, runId, verdictFile, testPlanFile, mcpFile, onLive = () => {} }) {
257	  fs.mkdirSync(path.dirname(verdictFile), { recursive: true });
258	  fs.rmSync(verdictFile, { force: true });
259	  const n = attempt?.n ?? 0;
260	
261	  if (game.status().mock) {
262	    const v = game.mockVerdict(plan, role === 'grader' ? 2 : n);
263	    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
264	    feed(mod, { attempt: n, role, kind: 'note', text: '[mock runtime] canned verdict' });
265	    return game.readVerdict(verdictFile, plan);
266	  }
267	
268	  for (let run = 1; run <= 2; run++) {
269	    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
270	    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId, verdictFile, testPlanFile })));
271	    const poll = setInterval(() => {
272	      if (!fs.existsSync(verdictFile)) return;
273	      onLive({ ...game.readVerdict(verdictFile, plan), live: true });
274	      save(mod);
275	    }, 1000);
276	    try {
277	      await agent(mod, attempt, role, { cwd, prompt: game.playtestPrompt(plan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
278	    } finally {
279	      clearInterval(poll);
280	    }
281	    const verdict = game.readVerdict(verdictFile, plan);
282	    if (verdict.finished) return verdict;
283	    feed(mod, { attempt: n, role: 'benana', kind: 'note', text: run === 1 ? `The ${role} stopped before finishing; running it again.` : `The ${role} did not finish the test plan.` });
284	  }
285	  return game.readVerdict(verdictFile, plan);
286	}
