288	// Attempt numbers run across the whole chat (playtest folders and the UI key on them); `previous` is null for a turn's first attempt.
289	async function runAttempt(mod, turnIndex, n, previous) {
290	  const turn = mod.turns[turnIndex];
291	  const first = !previous;
292	  const attempt = {
293	    n, turn: turnIndex, revision: first && Boolean(turn.revision),
294	    role: !first ? 'fixer' : mod.seed && !turn.revision ? 'seeded' : 'builder',
295	    status: 'running', startedAt: now(), sessions: [],
296	  };
297	  mod.attempts.push(attempt);
298	  save(mod);
299	
300	  setPhase(mod, first ? 'build' : 'fix', !first ? `Attempt ${n}: fixing what the playtester found` : `Attempt ${n}: ${attempt.revision ? 'changing' : 'writing'} ${mod.name}`);
301	  await codePhase(mod, attempt, previous);
302	
303	  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven and packing assets`);
304	  attempt.build = await repo.build(mod.repoDir, mod.name);
305	  const assets = attempt.build.assets;
306	  if (assets?.items?.length || assets?.errors?.length) {
307	    feed(mod, { attempt: n, role: 'benana', kind: 'assets', items: assets.items, errors: assets.errors, warnings: assets.warnings, text: `${assets.items.length} asset(s) drawn${assets.errors.length ? `, ${assets.errors.length} problem(s)` : ''}` });
308	  }
309	  if (!attempt.build.ok) {
310	    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
311	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
312	    return attempt;
313	  }
314	  if (assets && !assets.ok) {
315	    attempt.failure = { kind: 'assets', summary: `The resource pack is broken: ${assets.errors[0]}${assets.errors.length > 1 ? ` (+${assets.errors.length - 1} more)` : ''}` };
316	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): broken assets`);
317	    return attempt;
318	  }
319	  const did = attempt.role === 'fixer' ? `fix ${mod.name} from playtest evidence` : attempt.revision ? `change ${mod.name}: ${turn.prompt.replace(/\s+/g, ' ').slice(0, 72)}` : `implement ${mod.name}`;
320	  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${did}`);
321	  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });
322	  // An agent commit without a checkpoint has no record of the work behind it: say so, don't hide it.
323	  if (!attempt.commit.checkpoint && mod.partners?.entire?.enabled) {
324	    attempt.provenanceMissing = true;
325	    feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Entire did not link commit ${attempt.commit.sha.slice(0, 7)} to the agent session, so this attempt has no checkpoint.` });
326	  }
327	
328	  setPhase(mod, 'deploy', `Attempt ${n}: deploying to the Paper server`);
329	  attempt.deploy = await game.deployPlugin({ jarPath: attempt.build.jar, packPath: assets?.zip || null, emit });
330	  if (!attempt.deploy.loaded) {
331	    attempt.failure = { kind: 'load', summary: 'The plugin did not load on the server.' };
332	    return attempt;
333	  }
334	
335	  setPhase(mod, 'playtest', `Attempt ${n}: the AI player is testing ${mod.name} in-game`);
336	  attempt.verdict = await playtestPhase(mod, attempt);
337	  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
338	  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
339	  if (!attempt.verdict.passed) {
340	    const failed = attempt.verdict.checks.filter((c) => c.status !== 'pass');
341	    attempt.failure = attempt.verdict.finished
342	      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
343	      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
344	  }
345	  return attempt;
346	}
