348	// Benchmark grading: redeploy the final build on a fresh world, run the task's hidden checks with a grader session outside the
349	// mod repo (so no building agent can read them), score it, and have a coach turn the failures into lessons for future builders.
350	async function benchPhase(mod) {
351	  const task = bench.task(mod.bench.taskId);
352	  const started = now();
353	  const dir = path.join(studioDir, mod.id, 'bench');
354	  fs.mkdirSync(dir, { recursive: true });
355	  const build = latestBuild(mod);
356	  const plan = bench.goldPlan(task, mod);
357	  let verdict = null;
358	  if (build) {
359	    setPhase(mod, 'bench', `Benchmark: grading ${mod.name} with ${task.gold.checks.length} hidden checks`);
360	    const deploy = await game.deployPlugin({ jarPath: build.jar, packPath: packOf(mod), emit });
361	    if (deploy.loaded) {
362	      const testPlanFile = path.join(dir, 'test-plan.json');
363	      fs.writeFileSync(testPlanFile, JSON.stringify(plan, null, 2));
364	      verdict = await playtestRun(mod, null, {
365	        plan, role: 'grader', cwd: dir, runId: `${mod.id}_bench`,
366	        verdictFile: path.join(dir, 'verdict.json'), testPlanFile, mcpFile: path.join(dir, 'mcp.json'),
367	      });
368	    }
369	  }
370	  const scored = bench.score(task, verdict, build);
371	  const turnSessions = [...mod.sessions, ...mod.attempts.flatMap((a) => a.sessions)];
372	  const result = {
373	    id: `${mod.id}_bench`, taskId: task.id, modId: mod.id, modName: mod.name, at: now(), durationMs: now() - mod.createdAt,
374	    gradeMs: now() - started, attempts: mod.attempts.length, selfPassed: mod.attempts.some((a) => a.status === 'passed'),
375	    lessonsBefore: mod.bench.lessonsBefore, costUsd: turnSessions.reduce((n, s) => n + (s.usage?.costUsd || 0), 0),
376	    ...scored, lessonsLearned: [],
377	  };
378	  mod.bench.result = result;
379	  feed(mod, { role: 'benana', kind: 'bench', text: `Benchmark ${task.title}: ${scored.passed}/${scored.total} hidden checks passed`, result });
380	  save(mod);
381	
382	  const failed = scored.checks.filter((c) => c.status !== 'pass' && c.by === 'grader' && c.status !== 'blocked');
383	  if (failed.length && build && !game.status().mock) {
384	    setPhase(mod, 'bench', 'Benchmark: the coach is turning failed checks into lessons');
385	    const res = await agent(mod, null, 'coach', {
386	      cwd: mod.repoDir, prompt: prompts.coach({ task, mod, gold: scored, lessons: lessons().map((l) => l.lesson) }),
387	      model: MODELS.build, tools: ['Read', 'Glob', 'Grep'], allowedTools: ['Read', 'Glob', 'Grep'],
388	    }).catch((e) => ({ ok: false, error: e.message }));
389	    if (res.ok) {
390	      for (const m of res.final.matchAll(/^LESSON:\s*(.+)$/gm)) {
391	        const lesson = m[1].trim();
392	        if (addLesson(lesson, mod, 'coach')) result.lessonsLearned.push(lesson);
393	      }
394	      if (result.lessonsLearned.length) feed(mod, { role: 'benana', kind: 'note', text: `Coach added ${result.lessonsLearned.length} lesson(s) for future builders` });
395	    }
396	  }
397	  bench.record(result);
398	  emit('studio:bench', result);
399	  save(mod);
400	  return result;
401	}
