403	// Runs the mod's latest turn. The first turn builds the plugin from scratch; a revision turn (the repository already exists)
404	// updates the spec and test plan, changes the existing code, and playtests it again.
405	async function run(mod) {
406	  const turnIndex = mod.turns.length - 1;
407	  const turn = mod.turns[turnIndex];
408	  active = { modId: mod.id, stop: () => {}, stopped: false };
409	  // Records how the turn ended so older turns keep their own result once the chat moves on.
410	  const settle = (status, done) => {
411	    mod.status = status;
412	    turn.status = status;
413	    if (done) setPhase(mod, 'done', done);
414	    turn.endPhase = mod.phase;
415	  };
416	  try {
417	    if (game.status().bot !== 'online' && !game.status().mock) {
418	      setPhase(mod, 'game', 'Starting the Minecraft server');
419	      await game.start(emit);
420	    }
421	    mod.status = 'running';
422	    mod.error = null;
423	    setPhase(mod, 'spec', turn.revision ? 'Updating the spec and test plan for your change' : 'Writing the spec and an in-game test plan');
424	    const spec = await specPhase(mod, turn);
425	    mod.name = spec.modName;
426	    mod.spec = { summary: spec.summary, behavior: spec.behavior || [], assets: Array.isArray(spec.assets) ? spec.assets.filter((a) => a?.name) : [] };
427	    mod.testPlan = spec.testPlan;
428	    Object.assign(turn, { summary: spec.summary, checks: spec.testPlan.checks });
429	    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });
430	
431	    if (turn.revision) {
432	      fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
433	      fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
434	      await repo.commit(mod.repoDir, 'Update the in-game test plan');
435	    } else {
436	      setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
437	      const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
438	      mod.repoDir = created.dir;
439	      mod.partners = created.partners;
440	      fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
441	      fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
442	      await repo.commit(mod.repoDir, 'Add the in-game test plan');
443	    }
444	    save(mod);
445	
446	    let previous = null;
447	    let used = 0;
448	    const firstN = (mod.attempts.at(-1)?.n ?? 0) + 1;
449	    for (let n = firstN; n < firstN + MAX_ATTEMPTS; n++) {
450	      const attempt = await runAttempt(mod, turnIndex, n, previous);
451	      attempt.status = attempt.failure ? 'failed' : 'passed';
452	      attempt.endedAt = now();
453	      save(mod);
454	      if (!attempt.failure) {
455	        if (attempt.lesson) addLesson(attempt.lesson, mod);
456	        used = n - firstN + 1;
457	        break;
458	      }
459	      feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Attempt ${n} failed (${attempt.failure.kind}): ${attempt.failure.summary}` });
460	      previous = attempt;
461	    }
462	    // A benchmark run is graded on the final build whether or not it passed its own test plan.
463	    const graded = mod.bench && turnIndex === 0 ? await benchPhase(mod) : null;
464	    const tail = graded ? ` · benchmark ${graded.passed}/${graded.total}` : '';
465	    if (used) settle('passed', `${used === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${used} attempts`}${tail}`);
466	    else settle('failed', `${mod.name} still fails after ${MAX_ATTEMPTS} attempts${tail}`);
467	  } catch (e) {
468	    settle(active?.stopped ? 'stopped' : 'failed');
469	    mod.error = e.message;
470	    feed(mod, { role: 'benana', kind: 'error', text: e.message });
471	    log(`studio: ${e.message}`, 'error');
472	    save(mod);
473	  } finally {
474	    active = null;
475	    save(mod);
476	  }
477	}
