493	async function runDemo({ id }) {
494	  if (active) throw new Error('A mod is building. Run it after it finishes.');
495	  if (demoRun) throw new Error('A demo is already running.');
496	  const mod = mods.get(id);
497	  if (!mod?.testPlan) throw new Error('This mod has no spec yet.');
