500	  const run = { modId: id, stop: () => {}, stopped: false };
501	  demoRun = run;
502	  emitDemo();
503	  let summary = '';
504	  let error = null;
505	  try {
506	    if (!isLoaded(mod)) {
507	      const out = await game.deployPlugin({ jarPath: jar, packPath: packOf(mod), emit });
508	      if (!out.loaded) throw new Error(`${mod.name} did not load: ${out.errors[0] || 'see the server log'}`);
509	    } else if (game.status().bot !== 'online' && !game.status().mock) {
510	      await game.start(emit);
511	    }
512	    if (run.stopped) return { stopped: true };
513	    if (game.status().mock) return { summary: '[mock runtime] no demo' };
514	    game.clearShowcase();
515	    const dir = path.join(studioDir, mod.id, 'demo');
