519	    // Runs outside the mod repo so a demo is never traced or checkpointed as part of the mod's history.
520	    const handle = runClaude({ cwd: dir, prompt: game.demoPrompt(mod), model: MODELS.playtest, tools: [], allowedTools: game.demoTools, mcpConfigFile: mcpFile, timeoutMs: 9 * 60 * 1000 });
521	    run.stop = handle.stop;
522	    if (run.stopped) handle.stop();
523	    const res = await handle.done;
524	    if (run.stopped) return { stopped: true };
525	    if (!res.ok) throw new Error(res.error);
526	    summary = res.final.trim();
527	    return { summary };
528	  } catch (e) {
529	    error = e.message;
530	    throw e;
531	  } finally {
532	    demoRun = null;
533	    emitDemo({ summary, error });
534	  }
535	}
