// Drives the running Benana dev app over the DevTools protocol (BENANA_CDP_PORT).
//   node cdp.mjs eval "<js expression>"   evaluates in the renderer, awaits promises, prints the JSON result
//   node cdp.mjs shot <file.png>          screenshots the app window
//   node cdp.mjs invoke <channel> [json]  calls window.benana.invoke(channel, payload)
import fs from 'node:fs';

const port = process.env.BENANA_CDP_PORT || '9333';
const [cmd, ...rest] = process.argv.slice(2);

const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = targets.find((t) => t.type === 'page' && /5199|index\.html/.test(t.url));
if (!page) throw new Error(`No Benana page among ${targets.map((t) => t.url).join(', ')}`);
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const waiting = new Map();
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && waiting.has(msg.id)) { waiting.get(msg.id)(msg); waiting.delete(msg.id); }
};
const send = (method, params = {}) => new Promise((res) => { const n = ++id; waiting.set(n, res); ws.send(JSON.stringify({ id: n, method, params })); });

async function evaluate(expression) {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 2000));
  return r.result?.result?.value;
}

if (cmd === 'eval') {
  console.log(JSON.stringify(await evaluate(rest.join(' ')), null, 2));
} else if (cmd === 'invoke') {
  const payload = rest[1] ? rest[1] : '{}';
  console.log(JSON.stringify(await evaluate(`window.benana.invoke(${JSON.stringify(rest[0])}, ${payload})`), null, 2));
} else if (cmd === 'shot') {
  const r = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(rest[0], Buffer.from(r.result.data, 'base64'));
  console.log(rest[0]);
} else {
  console.error('usage: eval <js> | invoke <channel> [json] | shot <file>');
}
ws.close();

