// Prints a mod's progress from ~/.benana/studio/<id>/mod.json: phase, attempts, checks, and new feed lines since the last call.
//   node watch.cjs <modId> [sinceIndex]
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const [id, since = '0'] = process.argv.slice(2);
const mod = JSON.parse(fs.readFileSync(path.join(os.homedir(), '.benana', 'studio', id, 'mod.json'), 'utf8'));
const t = (ms) => new Date(ms).toTimeString().slice(0, 8);
console.log(`${mod.name} status=${mod.status} phase=${mod.phase} error=${mod.error || '-'} feed=${mod.feed.length}`);
for (const a of mod.attempts) {
  const cost = a.sessions.reduce((n, s) => n + (s.usage?.costUsd || 0), 0);
  console.log(`  attempt ${a.n} ${a.role} ${a.status}${a.failure ? ` (${a.failure.kind}: ${a.failure.summary.slice(0, 300)})` : ''} $${cost.toFixed(2)}`);
  for (const c of a.verdict?.checks || []) console.log(`    ${c.status.padEnd(7)} ${c.id}: ${String(c.observed || '').slice(0, 220)}`);
}
for (const item of mod.feed.slice(Number(since))) {
  const text = item.text || item.summary || (item.name ? `${item.name} ${item.summary || ''}` : '');
  if (item.kind === 'result' && !item.isError) continue;
  console.log(`${t(item.at)} [${item.attempt ?? '-'}:${item.role}:${item.kind}] ${String(text).replace(/\s+/g, ' ').slice(0, 260)}`);
}

