              }
            >
              {demo ? "Stop demo" : "Demo hits"}
            </button>
          )
        )}
        <button className={`game-btn ${mod ? "ghost" : ""}`} disabled={busy || reloading} onClick={toggle}>
          {busy ? "Working…" : running ? "Stop" : "Start game"}
